/* Lot 110: the body as a box scroller of its own, its timelines and its geometry record (generated by scripts/lot110_gen.py; expectations from scripts/lot110_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[6144];
static char g_o[1024];

static void prep(const char *css, int ms) {
    wf_site_set_time(ms);
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body>"
             "<div id=o><div id=b><p id=i>i</p><p id=r>r</p></div></div><p id=q>q</p></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare_ext(&g_d, g_html, (int)strlen(g_html), 640, 480, 0, 0));
    TEST_ASSERT_EQUAL(8, g_d.nnodes);
    wf_site_set_time(0);
}

/* the style attribute of the element with this id (html, body: by tag) */
static const char *style_of(const char *id) {
    int i;
    g_o[0] = 0;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, id) || (!g_d.node[i].id[0] && !strcmp(g_d.node[i].tag, id)))
            wf_site_style_attr(&g_d, g_d.node[i].start, g_o, (int)sizeof(g_o));
    return g_o;
}

static wf_geom_t g_g;

static void geo_clear(void) { memset(&g_g, 0, sizeof(g_g)); }
static void geo_root(int rgy, int scy) { geo_clear(); g_g.vw = 640; g_g.vh = 480; g_g.rg_y = rgy; g_g.sc_y = scy; }

/* the box of element k (html 0, head 1, body 2, #o 3, #b 4, #i 5),
 * -1 the body record */
static wf_geom_box_t *at(int k) { return k < 0 ? &g_g.body : &g_g.box[k]; }

static void geo(int k, int root, int bvert, int b_off, int b_size, int i_off, int i_size, int vp_b, int vp_i,
                int rg_b, int rg_i) {
    wf_geom_box_t *b = at(k);
    memset(b, 0, sizeof(*b));
    b->ok = 1; b->root = (unsigned char)root; b->bvert = (unsigned char)bvert;
    b->b_off = b_off; b->b_size = b_size; b->i_off = i_off; b->i_size = i_size;
    b->vp_b = vp_b; b->vp_i = vp_i; b->rg_b = rg_b; b->rg_i = rg_i;
    if (k >= 0) g_g.n++;
}

static void geo2(int k, int sm, int sc_b, int sc_i, int sv, int s_vp, int s_sc, int s_rg) {
    wf_geom_box_t *b = at(k);
    b->sm = sm; b->sc_b = sc_b; b->sc_i = sc_i; b->sv = (unsigned char)sv;
    b->s_vp = s_vp; b->s_sc = s_sc; b->s_rg = s_rg;
}

static void prep3(const char *css, int ms, int pm, int gui, int with_geom) {
    wf_site_set_geom(with_geom ? &g_g : 0);
    wf_site_set_scroll(pm);
    wf_site_set_scroll_gui(gui);
    prep(css, ms);
    wf_site_set_scroll(0);
    wf_site_set_scroll_gui(0);
    wf_site_set_geom(0);
}

/* animated, scroll, view, box, idle, need, used, live */
static const char *counts(void) {
    snprintf(g_o, sizeof(g_o), "%d %d %d %d %d %d %d %d", g_d.col_animated, g_d.anim_scroll, g_d.anim_view,
             g_d.anim_box, g_d.anim_idle, g_d.geom_need, g_d.geom_used, g_d.geom_live);
    return g_o;
}

/* geo and scr of html, body, #o, #b, #i */
static const char *flags(void) {
    static const int at5[5] = {0, 2, 3, 4, 5};
    int k;
    for (k = 0; k < 5; k++) { g_o[2 * k] = (char)('0' + g_d.node[at5[k]].geo); g_o[2 * k + 1] = (char)('0' + g_d.node[at5[k]].scr); }
    g_o[10] = 0;
    return g_o;
}

